import {RAIN_MODEL,RAIN_CASES,RAIN_COLUMNS,rainQuestions} from './rain-paths-content.mjs';
import {rainPaths,currentRainView,rainResult,rainPlanView,chooseRainCase,setRainView,setRainPage,setRainPrediction,useRainSupport,nextRainPhase,restartRainCase,setRainPending,submitRainComparison,keepRainResult,chooseRainPlan,setRainPlanRoute,nextRainPlan,keepRainPlan,recoverRainPaths,rainDisplayExposure} from './rain-paths-core.mjs';
import {rainMachineArt,rainPlanArt} from './rain-paths-art.mjs';
import {rainNotebookInvitationPanel} from './rain-notebook-bridge.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['predict','Choose & predict'],['rain','Rain & follow'],['compare','Compare'],['plan','Plan & keep']];
let clearResize=()=>{};
const btn=(attr,id,label,on=false)=>`<button type="button" class="secondary ${on?'selected':''}" data-rp-${attr}="${esc(id)}" aria-pressed="${on}">${esc(label)}</button>`;
const factorLabel=c=>c.factor==='cover'?'Entrance or lid':'Starting stored water';
const trayLabel=r=>`Tray ${r.id}: ${r.cover==='open'?'open entrance':'sealed lid'}, ${r.priorStored} already stored`;
const expose=(results,facts='')=>`data-rp-expose data-rp-results="${results}" data-rp-facts="${facts}"`;
const tokenLegend=()=>'<p class="rp-legend"><span><i class="rp-new-token" aria-hidden="true"></i> New rain token</span><span><i class="rp-prior-token" aria-hidden="true"></i> Already here before this rain</span></p>';
function ledger(rows,complete){return `<div class="rp-ledgers" ${expose(rows.some(r=>r.cloudRemaining<r.newRainTotal))}>${rows.map(r=>`<section class="rp-ledger"><h3>${esc(trayLabel(r))}</h3><p>${r.newRainTotal} new tokens for this tray${complete?' · complete run':' · so far'}</p><dl>${[['Cloud reserve',r.cloudRemaining],['Surface',r.surfaceNew],['Newly stored',r.storedNew],['New runoff',r.runoffNew]].map(([label,n])=>`<div><dt>${label}</dt><dd>${n}</dd></div>`).join('')}</dl><details><summary>Count every token in this tray</summary><p>New rain: ${r.newRainTotal} = ${r.cloudRemaining} cloud + ${r.surfaceNew} surface + ${r.storedNew} newly stored + ${r.runoffNew} runoff.</p><p>Including earlier water: ${r.priorStored+r.newRainTotal} = ${r.priorStored} already stored + ${r.cloudRemaining} cloud + ${r.surfaceNew} surface + ${r.storedNew} newly stored + ${r.runoffNew} runoff.</p><p>${r.emptySlots} empty storage slots remain. Earlier tokens stay in their starting slots in this toy.</p></details></section>`).join('')}</div>`;}
function machines(v,{example=false}={}){const shownTray=v.views.tray;return `<div class="rp-machine-pair ${example?'rp-example-machines':''}">${example?'':`<div class="rp-tray-tabs" role="group" aria-label="Drawing to inspect">${['A','B'].map(id=>btn('tray',id,`Inspect tray ${id}`,shownTray===id)).join('')}</div>`}${v.trays.map(r=>`<figure class="rp-machine ${shownTray===r.id?'rp-active-tray':''}" data-rp-machine="${r.id}" ${expose(v.progress>0,`3x4${r.priorStored===8?',2x4':''}`)}><figcaption><strong>${esc(trayLabel(r))}</strong><span>${r.newRainTotal} new tokens on this tray</span></figcaption>${rainMachineArt(r,{prefix:`${example?'example':'source'}-${v.case.id}-${r.id}`})}</figure>`).join('')}</div>${tokenLegend()}`;}
function table(rows,{complete=true,title='Matched machine counts'}={}){return `<section class="rp-source-table" ${expose(rows.some(r=>r.cloudRemaining<r.newRainTotal))}><h3>${esc(title)}${complete?'':' · so far'}</h3><p class="tiny">Arbitrary model-water tokens, per tray. ${complete?'Completed source result.':'Cloud and surface tokens are still in the apparatus; this is not a final result.'}</p><div class="rp-table-scroll"><table><thead><tr><th scope="col">Tray</th>${RAIN_COLUMNS.map(c=>`<th scope="col">${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.id}</th><td>${r.cover==='open'?'Open entrance':'Sealed lid'}</td><td>${r.priorStored}</td><td>${r.newRainTotal}</td><td>${r.storedNew}</td><td>${r.runoffNew}</td></tr>`).join('')}</tbody></table></div><p class="tiny">${esc(RAIN_MODEL.notice)}</p></section>`;}
function currentStep(v){if(v.complete)return 'Every new token has reached a storage slot or the runoff collector. The cloud and surface are empty.';if(v.phase==='bring')return `Bring four new rain tokens down onto EACH tray. Batch ${v.batch} of ${v.batches}. A batch is a group of tokens, not a time interval.`;if(v.phase==='opening')return v.trays.map(r=>r.cover==='sealed'?`Tray ${r.id}: the solid lid blocks the entrance. None of its ${r.surfaceNew} surface tokens can enter, even with ${r.emptySlots} empty slots.`:`Tray ${r.id}: the entrance is open, with ${r.emptySlots} empty slots. ${Math.min(r.surfaceNew,r.emptySlots)} of its ${r.surfaceNew} surface tokens can enter.`).join(' ');return v.trays.map(r=>`Tray ${r.id}: follow ${r.surfaceNew} surface token${r.surfaceNew===1?'':'s'} to its new-runoff collector${r.surfaceNew===0?' (zero move; none are added)':''}.`).join(' ');}
function predict(v){const p=v.work.prediction.latest;return `<h2 id="rp-title" tabindex="-1">Where might this new rain go?</h2><p>Which tray might send more of this new rain to the outlet?</p><div role="group" class="rp-choices" aria-label="Optional prediction">${[['A','Tray A'],['B','Tray B'],['same','The same amount'],['unsure','Not sure']].map(([id,label])=>btn('prediction',id,label,p?.choice===id)).join('')}</div><p class="tiny">Optional and unscored. ${p?`Latest prediction: ${esc(p.choice==='same'?'the same amount':p.choice==='unsure'?'not sure':`tray ${p.choice}`)}. ${p.timing==='after-results'?'A result from this model pack had already been shown.':p.timing==='unknown'?'Earlier result exposure is uncertain.':'No result from this model pack had been shown when this prediction was recorded.'}`:'You can move the water without making a prediction.'}</p><button type="button" class="primary" data-rp-page="rain">Try the machine steps</button>${machines(v)}${ledger(v.trays,v.complete)}`;}
function rain(v){return `<h2 id="rp-title" tabindex="-1">${v.complete?'Followed every new token':`Batch ${v.batch} of ${v.batches}: ${v.phase==='bring'?'bring down the rain':v.phase==='opening'?'follow the opening':'follow the surface water'}`}</h2><div class="rp-next-step" id="rp-step-status" role="status" tabindex="-1"><p>${esc(currentStep(v))}</p>${v.complete?'<button type="button" class="primary" data-rp-page="compare">Compare these results</button>':`<button type="button" class="primary" data-rp-phase>${v.phase==='bring'?'Bring down four on each tray':v.phase==='opening'?'Follow the opening on both trays':'Follow surface water to both outlets'}</button>`}</div>${machines(v)}${ledger(v.trays,v.complete)}<div class="rp-controls">${v.complete?'<button type="button" class="secondary" data-rp-keep-result>Keep this completed result</button>':''}<button type="button" class="text-button" data-rp-restart>Restart this case from its starting water</button></div><p class="tiny">Restart explicitly refills the cloud for familiar practice. Earlier predictions, checks, kept results and planning boards stay in your notes.</p>`;}
function questionFeedback(v,task){const a=v.work.checks.filter(x=>x.task===task).at(-1);if(!a)return '';const pending=v.work.pending[task],same=JSON.stringify(a.response)===JSON.stringify(pending)&&a.shown.progress===v.progress;return `<section class="rp-feedback" id="rp-feedback" role="status" tabindex="-1">${same?`<strong>${a.correct?'This response fits the shown comparison.':'Keep comparing the supplied controls and counts.'}</strong><p>${esc(rainQuestions(v.case.id).find(q=>q.id===task).feedback)}</p>`:'<p>An earlier check is kept. Check again when you want feedback on this changed draft.</p>'}<p class="tiny">${task==='factor'?'Supplied-control practice':'Visible-source table practice'}${a.familiar?' · familiar work':''}. Help at the time of the check stays with it. This is not an independent experiment.</p></section>`;}
function compare(state,v){const shownQuestion=v.views.question,q=rainQuestions(v.case.id).find(q=>q.id===shownQuestion),pending=v.work.pending[q.id],available=q.id==='factor'||v.complete;return `<h2 id="rp-title" tabindex="-1">What can these counts tell us?</h2>${table(v.trays,{complete:v.complete})}<div role="group" class="rp-question-tabs" aria-label="Optional comparison questions">${[['factor','Changed factor'],['runoff','New runoff'],['columns','Useful columns'],['difference','Difference']].map(([id,label])=>btn('question',id,label,shownQuestion===id)).join('')}</div><form id="rp-comparison" novalidate data-rp-task="${q.id}"><fieldset ${available?'':'disabled'}><legend>${esc(q.prompt)}</legend>${q.id==='columns'?q.choices.map(c=>`<label><input type="checkbox" name="columns" value="${c.id}" ${pending.includes(c.id)?'checked':''}>${esc(c.label)}</label>`).join(''):q.id==='difference'?`<label for="rp-difference">Difference in model-water tokens<input id="rp-difference" name="difference" type="text" inputmode="numeric" autocomplete="off" maxlength="16" value="${esc(pending)}" placeholder="Leave blank if you like"></label>`:q.choices.map(c=>`<label><input type="radio" name="choice" value="${c.id}" ${pending===c.id?'checked':''}>${esc(c.label)}</label>`).join('')}<button type="submit" class="secondary">Check this optional response</button></fieldset>${available?'':'<p>Finish the manual rain steps to compare a completed matching result. This partial ledger stays inspectable.</p>'}<p id="rp-form-status" role="status"></p></form>${questionFeedback(v,q.id)}<p>Wonder together: “I saw…” or “I think the model did that because…” Visible counts and the rule we chose are different kinds of statements. Your conversation is not recorded or scored.</p><div class="rp-controls">${v.complete?'<button type="button" class="secondary" data-rp-keep-result>Keep this completed result</button>':''}<button type="button" class="primary" data-rp-page="plan">Try an outlet plan</button></div>${v.complete?rainNotebookInvitationPanel(state,{caseId:v.case.id,origin:'current-completed'}):''}`;}
function keptPlanView(p){const total=p.source.rows.find(r=>r.id===p.trayId).runoffNew,cup=p.route==='holding12'?Math.min(12,p.sent):0;return {...p,total,reserve:total-p.sent,cup,lowPath:p.sent-cup,complete:p.sent===total};}
function plan(state,v){const shownPlan=v.views.planTray,selected=rainPlanView(state,shownPlan),source=selected?.source||rainResult(state)||v.keptResult||v.work.plans.A?.source||v.work.plans.B?.source,kept=v.work.keptPlans[shownPlan];return `<h2 id="rp-title" tabindex="-1">Try a copy on the planning board</h2><p>Choose a completed source tray. The board tries a copy of its new runoff; the source machine stays exactly as it was.</p>${source?`${table(source.rows,{title:`Frozen source: ${source.config.label}`})}<div class="rp-controls" role="group" aria-label="Source tray to try">${['A','B'].map(id=>btn('plan-tray',id,`Try tray ${id} · ${source.rows.find(r=>r.id===id).runoffNew} runoff`,shownPlan===id)).join('')}</div><div class="rp-routes"><button type="button" class="secondary ${selected?.route==='straight'?'selected':''}" data-rp-route="straight">${selected?'Restart copy: straight channel':'Start copy: straight channel'}</button><button type="button" class="secondary ${selected?.route==='holding12'?'selected':''}" data-rp-route="holding12">${selected?'Restart copy: holding cup':'Start copy: holding cup'}</button></div><p class="tiny">A straight channel sends every token onward. The holding cup has 12 empty spaces and no leak or outlet during this demonstration. Choosing a route explicitly restarts this copy.</p>`:'<p>No completed source is available for this case yet. Visit Rain & follow to move its tokens, or choose a case with a kept result.</p><button type="button" class="secondary" data-rp-page="rain">Return to the rain machine</button>'}${selected?`<section class="rp-planning-board" ${expose(true,selected.route==='holding12'?'3x4':'')}><h3>Trying this result again on a planning board · tray ${shownPlan}</h3>${rainPlanArt(selected)}<p id="rp-plan-status" role="status" tabindex="-1">${selected.total===0?'No new runoff arrived from this source. Both routes honestly have no new tokens.':selected.complete?`In this closed toy, the cup held ${selected.cup} and ${selected.lowPath} continued to the low-path collector.`:`${selected.reserve} remain in reserve, ${selected.cup} are in the cup and ${selected.lowPath} reached the low-path collector.`}</p><div class="rp-controls">${selected.complete?'<button type="button" class="primary" data-rp-keep-plan>Keep this plan</button>':'<button type="button" class="primary" data-rp-plan-step>Send the next group of up to four</button>'}</div><p class="tiny">${selected.total} source runoff = ${selected.reserve} reserve + ${selected.cup} cup + ${selected.lowPath} low path. Keeping either route, including overflow, is not a safety verdict.</p></section>`:''}${kept?`<details class="rp-kept"><summary>Last kept plan for tray ${shownPlan}</summary><div ${expose(true,kept.route==='holding12'?'3x4':'')}><p>This frozen copy keeps its source and support, even while you try a different route.</p>${rainPlanArt(keptPlanView(kept),{prefix:`kept-${v.case.id}-${shownPlan}`})}</div></details>`:''}<p><a href="#science">Return to Water Lab</a> <span aria-hidden="true"> · </span><a href="#notes">Grown-up notes</a></p>`;}
function exampleView(v){const local={};chooseRainCase(local,v.case.id==='cover-12'?'space-12':'cover-12');while(!currentRainView(local).complete)nextRainPhase(local);return currentRainView(local);}
function support(v,page){const flags=v.work.support.global,example=flags.example?exampleView(v):null;const say=`${RAIN_MODEL.limitation} ${page==='rain'?currentStep(v):page==='predict'?'Which tray might send more of this new rain to the outlet? Make an optional prediction or try the machine steps.':page==='compare'?'Compare the supplied controls and completed new-runoff counts. Already-stored water is not a destination of new rain.':'Try a copy of a completed result in a straight channel or a holding cup. The source result stays unchanged.'}`;return `<aside class="rp-support" tabindex="-1"><div class="rp-controls"><button type="button" class="secondary" data-rp-support="help">Why here?</button><button type="button" class="secondary" data-rp-support="example">A different worked example</button><button type="button" class="secondary" data-rp-support="together" aria-pressed="${!!flags.together}">${flags.together?'Working together is kept':'We’re working together'}</button><span data-rp-audio>${hearButton(say,'Hear this turn')}</span></div>${flags.help?'<p>The solid lid blocks the entrance. An open entrance admits new tokens only into empty storage slots. Surface tokens then go to the outlet. These are rules of our closed machine; real ground can let water move through more paths.</p>':''}${example?`<section class="rp-example" tabindex="-1"><h3>A different completed model example</h3><p>${esc(example.case.label)}. Each machine received ${example.case.newRainTotal} new tokens. Only ${factorLabel(example.case).toLowerCase()} changed.</p>${machines(example,{example:true})}${table(example.trays,{title:'Worked example results'})}<p>Follow the labeled storage spaces and outlet collectors. This example does not add water to your machine or fill in your responses.</p></section>`:''}</aside>`;}
export function rainPathsEntry(){return '<aside class="rp-entry"><div><h2>Follow the rain, token by token</h2><p>Try two tabletop water-path machines, compare their outlets, then test a small holding-cup plan.</p></div><a class="secondary" href="#science/rain">Visit Rain Paths</a></aside>';}
export function rainPathsPage(state){const r=rainPaths(state);if(!r)return '<section class="panel rp-workspace"><a href="#science">Back to Water Lab</a><h1 id="rp-title" tabindex="-1">An earlier Rain Paths record is kept</h1><p>This format cannot be opened here. Its exact original stays in notes downloads.</p><button type="button" class="secondary" data-rp-recover>Keep the earlier record and start fresh</button></section>';const v=currentRainView(state);return `<div class="rp-workspace rp-page-${r.page}"><header><a class="back" href="#science">Back to Water Lab</a><h1>Rain Paths</h1><p>The low path is wet. What could change the amount that reaches an outlet?</p></header><div class="rp-case-strip"><details><summary>${esc(v.case.label)} · choose a case</summary><div class="rp-case-grid">${RAIN_CASES.map(c=>btn('case',c.id,c.label,r.currentCase===c.id)).join('')}</div></details><p><strong>Only changed factor:</strong> ${factorLabel(v.case)}. Each tray gets ${v.case.newRainTotal} new tokens; both chambers have 12 slots.${v.work.familiar||r.resultsExposed||r.exposureUnknown?' Familiar model practice.':''}</p></div><nav class="rp-pages" aria-label="Rain Paths turn">${pages.map(([id,label],i)=>btn('page',id,`${i+1}. ${label}`,r.page===id)).join('')}</nav><p class="rp-limitation">${esc(RAIN_MODEL.limitation)}</p><section class="rp-task">${r.page==='predict'?predict(v):r.page==='rain'?rain(v):r.page==='compare'?compare(state,v):plan(state,v)}</section>${v.keptResult&&r.page!=='plan'?`<details class="rp-kept"><summary>Return to this case’s kept result</summary>${table(v.keptResult.rows,{title:'Kept completed source result'})}<p>This frozen table survives a restarted or partly completed run.</p>${rainNotebookInvitationPanel(state,{caseId:v.case.id,origin:'kept-completed'})}</details>`:''}${support(v,r.page)}<details class="rp-details"><summary>Our pretend model: controls, limits and sources</summary><p ${expose(false,'3x4')}>${esc(RAIN_MODEL.controls)}</p>${RAIN_MODEL.details.map(x=>`<p>${esc(x)}</p>`).join('')}<p>These qualitative sources do not supply our token capacities, routes, counts or drawings.</p><ul>${RAIN_MODEL.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a></li>`).join('')}</ul></details><div class="rp-footer"><a href="#science">Take a break in Water Lab</a><a href="#notes">Grown-up notes</a></div></div>`;}
function visible(el){return !!el.getClientRects().length;}
function shownExposure(state){const base=rainDisplayExposure(state,{view:'compare'}),facts=[],nodes=[...document.querySelectorAll('[data-rp-expose]')].filter(visible);for(const el of nodes)for(const key of (el.dataset.rpFacts||'').split(',').filter(Boolean)){const pair=key.split('x').map(Number);if(!facts.some(p=>p[0]===pair[0]&&p[1]===pair[1]))facts.push(pair);}return {results:nodes.some(el=>el.dataset.rpResults==='true'),unknown:base.unknown,facts};}
export function bindRainPaths(state,ctx){
 clearResize();clearResize=()=>{};
 if(!document.querySelector('.rp-workspace'))return;
 const shownQuestion=currentRainView(state)?.views.question??'factor',shownPlan=currentRainView(state)?.views.planTray??'A';
 const stale=()=>{const el=document.querySelector('#rp-feedback');if(el)el.textContent='An earlier check is kept in your notes. Check again for feedback on this edited response.';};
 const emit=()=>ctx.expose?.(shownExposure(state)),refresh=(target='#rp-title')=>{ctx.save();ctx.render();ctx.focus?.(target);},act=(fn,target)=>{if(fn())refresh(target);};
 document.querySelectorAll('[data-rp-page]').forEach(b=>b.onclick=()=>act(()=>setRainPage(state,b.dataset.rpPage)));
 document.querySelectorAll('[data-rp-case]').forEach(b=>b.onclick=()=>{if(chooseRainCase(state,b.dataset.rpCase)){setRainPage(state,'predict');refresh();}});
 document.querySelectorAll('[data-rp-tray]').forEach(b=>b.onclick=()=>{const shownTray=b.dataset.rpTray;setRainView(state,'tray',shownTray);ctx.save();document.querySelectorAll('[data-rp-machine]').forEach(el=>el.classList.toggle('rp-active-tray',el.dataset.rpMachine===shownTray));document.querySelectorAll('[data-rp-tray]').forEach(el=>{el.classList.toggle('selected',el.dataset.rpTray===shownTray);el.setAttribute('aria-pressed',String(el.dataset.rpTray===shownTray));});emit();});
 document.querySelectorAll('[data-rp-prediction]').forEach(b=>b.onclick=()=>act(()=>setRainPrediction(state,b.dataset.rpPrediction),`[data-rp-prediction="${b.dataset.rpPrediction}"]`));
 document.querySelector('[data-rp-phase]')?.addEventListener('click',()=>act(()=>nextRainPhase(state),currentRainView(state).progress+1===currentRainView(state).batches*3?'#rp-step-status':'[data-rp-phase]'));
 document.querySelector('[data-rp-restart]')?.addEventListener('click',()=>act(()=>restartRainCase(state),'#rp-step-status'));
 document.querySelectorAll('[data-rp-question]').forEach(b=>b.onclick=()=>{setRainView(state,'question',b.dataset.rpQuestion);refresh(`[data-rp-question="${b.dataset.rpQuestion}"]`);});
 document.querySelectorAll('#rp-comparison input[type=radio]').forEach(input=>input.addEventListener('change',()=>{setRainPending(state,shownQuestion,input.value);stale();ctx.save();}));
 document.querySelectorAll('#rp-comparison input[type=checkbox]').forEach(input=>input.addEventListener('change',()=>{const values=[...document.querySelectorAll('#rp-comparison input[type=checkbox]:checked')].map(x=>x.value);if(!setRainPending(state,'columns',values)){input.checked=false;document.querySelector('#rp-form-status').textContent='Choose two columns. Uncheck one to change your pair.';}else{stale();ctx.save();}}));
 document.querySelector('#rp-difference')?.addEventListener('input',e=>{setRainPending(state,'difference',e.target.value);stale();ctx.save();});
 document.querySelector('#rp-comparison')?.addEventListener('submit',e=>{e.preventDefault();const result=submitRainComparison(state,shownQuestion);if(result?.valid)refresh('#rp-feedback');else document.querySelector('#rp-form-status').textContent=result?.error||'Finish the matching run before checking this response.';});
 document.querySelectorAll('[data-rp-keep-result]').forEach(b=>b.onclick=()=>{if(keepRainResult(state)){refresh('#rp-title');const status=document.querySelector('#rp-step-status');if(status)status.insertAdjacentHTML('beforeend','<p role="status">This completed result is kept. It stays with this case.</p>');}});
 document.querySelectorAll('[data-rp-plan-tray]').forEach(b=>b.onclick=()=>{setRainView(state,'planTray',b.dataset.rpPlanTray);refresh(`[data-rp-plan-tray="${b.dataset.rpPlanTray}"]`);});
 document.querySelectorAll('[data-rp-route]').forEach(b=>b.onclick=()=>{const action=rainPlanView(state,shownPlan)?setRainPlanRoute:chooseRainPlan;act(()=>action(state,shownPlan,b.dataset.rpRoute),'#rp-plan-status');});
 document.querySelector('[data-rp-plan-step]')?.addEventListener('click',()=>act(()=>nextRainPlan(state,shownPlan),rainPlanView(state,shownPlan).reserve<=4?'#rp-plan-status':'[data-rp-plan-step]'));
 document.querySelector('[data-rp-keep-plan]')?.addEventListener('click',()=>{if(keepRainPlan(state,shownPlan)){refresh('#rp-plan-status');document.querySelector('#rp-plan-status').textContent+=' This plan is kept, including any overflow.';}});
 document.querySelectorAll('[data-rp-support]').forEach(b=>b.onclick=()=>act(()=>useRainSupport(state,b.dataset.rpSupport),b.dataset.rpSupport==='example'?'.rp-example':'.rp-support'));
 document.querySelectorAll('[data-rp-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{useRainSupport(state,'audio');ctx.save();emit();}));
 document.querySelector('[data-rp-recover]')?.addEventListener('click',()=>act(()=>recoverRainPaths(state)));
 document.querySelectorAll('.rp-workspace details').forEach(el=>el.addEventListener('toggle',emit));
 if(globalThis.window?.addEventListener){window.addEventListener('resize',emit);clearResize=()=>window.removeEventListener('resize',emit);}
 emit();
}
export function rainPathsNotes(state){if(!Object.hasOwn(state,'rainPaths'))return '';return `<details class="panel" data-rp-notes><summary>Rain Paths: machine counts, comparisons and outlet plans</summary><p>Original closed-machine tokens, not measured hydrology, a flood forecast or a safety verdict. First and latest predictions keep their recorded exposure timing. Pending forms, support, familiar replays, visible-source practice and frozen source/plan snapshots remain separate. Notes expose saved model counts when opened; numeric co-occurrence alone is not multiplication practice.</p><div ${expose(rainDisplayExposure(state,{view:'notes'}).results)}><pre>${esc(JSON.stringify(state.rainPaths,null,2))}</pre></div></details>`;}
